import {initialState,cleanState,phases,checks,progress,validDomain,validPassword,validIP} from './engine.js';
import {createSimulator} from './os.js';
const $ = (s,r=document)=>r.querySelector(s);
const esc = s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const paths={server:'M4 3h16v7H4z M4 14h16v7H4z M7 6.5h1 M7 17.5h1 M12 6.5h5 M12 17.5h5',power:'M12 2v10 M5.5 5.5a9 9 0 1 0 13 0',usb:'M12 3v15a3 3 0 1 1-3-3h3 M9 6l3-3 3 3 M12 12l5-4V5 M12 10L7 7V5 M5 3h4v2H5z M16 2h2v3h-2z',network:'M8 3h8v6H8z M3 15h6v6H3z M15 15h6v6h-6z M12 9v3 M6 15v-3h12v3',monitor:'M3 4h18v13H3z M12 17v4 M8 21h8',check:'M5 12l4 4L19 6',chevron:'M9 5l7 7-7 7',down:'M5 9l7 7 7-7',book:'M3 4h7l2 2 2-2h7v15h-7l-2 2-2-2H3z M12 6v15',reset:'M3 11a9 9 0 1 1 2 7 M3 4v7h7',expand:'M8 3H3v5 M16 3h5v5 M21 16v5h-5 M8 21H3v-5',help:'M9 8a3 3 0 1 1 5 2c-2 1-2 2-2 4 M12 18h.01 M21 12a9 9 0 1 1-18 0 9 9 0 0 1 18 0',shield:'M12 2L3 6v6c0 5 9 10 9 10s9-5 9-10V6z M8 12l3 3 5-6',clock:'M12 7v5l3 2 M21 12a9 9 0 1 1-18 0 9 9 0 0 1 18 0',arrow:'M4 12h16 M14 6l6 6-6 6',close:'M6 6l12 12 M6 18L18 6',folder:'M3 5h7l2 3h9v12H3z',user:'M16 7a4 4 0 1 1-8 0 4 4 0 0 1 8 0 M4 21v-3a8 6 0 0 1 16 0v3',terminal:'M3 4h18v16H3z M6 8l4 4-4 4 M13 16h5',settings:'M12 8a4 4 0 1 1 0 8 4 4 0 0 1 0-8 M8 3h8l1 4 4 1v8l-4 1-1 4H8l-1-4-4-1V8l4-1z',flag:'M5 22V3 M5 3c5-4 9 4 15 0v11c-6 4-10-4-15 0',disk:'M4 3h16v18H4z M8 7h8 M9 16a3 3 0 1 0 6 0 3 3 0 0 0-6 0',windows:'M3 4l8-1v8H3z M13 3l8-1v9h-8z M3 13h8v8l-8-1z M13 13h8v9l-8-1z',trash:'M3 6h18 M9 6V3h6v3 M6 6l1 15h10l1-15 M10 10v7 M14 10v7',save:'M4 3h13l4 4v14H3V3z M7 3v6h10V3 M7 21v-8h10v8'};
function icon(name,cls=''){return `<svg class="${cls}" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.6" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true"><path d="${paths[name]||paths.server}"/></svg>`;}
let state;try{state=cleanState(JSON.parse(localStorage.getItem('serverlab-save')));}catch{state=initialState();}
let expanded=progress(state).phase, fullscreen=false, guideOpen=false, resetOpen=false;
const sim=createSimulator({get:()=>state,icon,esc,toast,render,commit:(changes,message)=>{const before=progress(state).done;Object.assign(state,changes);if(message)event(message);else save();if(progress(state).done>before)expanded=progress(state).phase;render();}});
function save(){try{localStorage.setItem('serverlab-save',JSON.stringify(state));}catch{toast('Your browser could not save progress. Keep this tab open.');}}
function event(message){state.events.unshift({message,time:new Date().toLocaleTimeString()});state.events=state.events.slice(0,50);save();}
function toast(message){const el=$('#toast');el.textContent=message;el.classList.add('show');clearTimeout(toast.timer);toast.timer=setTimeout(()=>el.classList.remove('show'),3800);}
function render(){const p=progress(state);document.body.classList.toggle('fullscreen',fullscreen);$('#app').innerHTML=`<div class="shell"><header class="topbar"><div class="brand"><span class="brand-mark">${icon('server')}</span><div>SERVERLAB<small>VIRTUAL TRAINING LAB</small></div></div><nav class="nav" aria-label="Main navigation"><button class="active" data-action="lab">Workspace</button><button data-action="guide">Field guide ${icon('book')}</button><a href="./about.html">About</a></nav><div class="top-meta"><span>Learning by doing.</span><span class="tag">SANDBOX</span><div class="avatar">IT</div></div></header><section class="intro"><div><div class="eyebrow"><span>LAB 01</span> / SYSTEM ADMINISTRATION</div><h1>Build your first domain.</h1><p>From a blank server to a connected organization. You’re in control.</p></div><button class="outline-btn" data-action="reset">${icon('reset')} Reset lab</button></section><main class="workspace"><section class="workstation" aria-label="Virtual computer"><div class="station-bar"><div class="station-label">${icon('monitor')} Workstation 01</div><div class="station-right"><span><i class="status-dot ${state.power?'on':''}"></i>${state.power?'POWERED ON':'POWERED OFF'}</span><button class="icon-btn" data-action="fullscreen" aria-label="${fullscreen?'Exit':'Enter'} focus mode" title="Focus mode">${icon('expand')}</button></div></div><div class="monitor"><div class="viewport" id="viewport"><div class="screen" id="screen" tabindex="0" aria-label="Simulated computer display">${renderScreen()}</div></div><div class="monitor-chin">SERVERLAB <i class="${state.power?'on':''}"></i></div></div><div class="console-note">${icon('help')} ${state.screen==='off'?'Connect your devices below, then power on the workstation.':'Click inside the display to interact. BIOS: F2 / Delete · Boot menu: F12.'}</div><div class="hardware-header"><span>HARDWARE CONNECTIONS</span><span>Click to connect or disconnect</span></div><div class="hardware-grid"><button class="hardware ${state.usb?'connected':''}" data-action="usb" aria-pressed="${state.usb}"><span class="hardware-visual">${icon('usb')}</span><div><h3>Ventoy USB drive</h3><p>${state.usb?'Connected · USB 3.0':'32 GB · Not connected'}</p></div><span class="connection-action">${state.usb?'−':'+'}</span></button><button class="hardware ${state.ethernet?'connected':''}" data-action="ethernet" aria-pressed="${state.ethernet}"><span class="hardware-visual">${icon('network')}</span><div><h3>Ethernet cable</h3><p>${state.ethernet?'Connected · 1 Gbps':'RJ45 · Not connected'}</p></div><span class="connection-action">${state.ethernet?'−':'+'}</span></button><button class="hardware power ${state.power?'connected':''}" data-action="power" aria-pressed="${state.power}"><span class="hardware-visual">${icon('power')}</span><div><h3>${state.power?'Power off':'Power on'}</h3><p>${state.power?'Server is running':'Server is off'}</p></div><span class="connection-action">${icon('arrow')}</span></button></div><div class="connection-caption">${icon('shield')} Isolated simulation. Your actual computer stays untouched.</div>${p.done===p.total?'<div class="complete-banner">✓ Mission complete. Your domain, users, and shared folder are ready. Keep exploring or reset the lab.</div>':''}</section><aside class="mission" aria-label="Mission checklist"><div class="mission-heading"><div class="mission-kicker">${icon('flag')} YOUR MISSION</div><h2>Windows Server setup</h2><p>Install the OS. Create a domain.<br>Set up your users and shared folders.</p><div class="progress-meta"><span>${p.done} of ${p.total} tasks completed</span><strong>${p.percent}%</strong></div><div class="progress-track" role="progressbar" aria-label="Mission progress" aria-valuenow="${p.percent}" aria-valuemin="0" aria-valuemax="100"><div style="width:${p.percent}%"></div></div></div>${renderPhases()}<div class="mission-help">${icon('help')} A little help goes a long way.<button data-action="hint">Get a hint ${icon('arrow')}</button></div></aside></main><footer class="bottom-bar"><span>${icon('save')} Progress saved on this device</span><span>Windows Server 2012 R2 <span>·</span> Educational simulation</span><span>${icon('clock')} Go at your own pace</span></footer></div>${guideOpen?renderGuide():''}`; fitScreen();}
function renderPhases(){const c=checks(state);return phases.map((p,i)=>{const done=p.items.filter(([k])=>c[k]).length;return `<section class="phase ${i===expanded?'active':''} ${done===p.items.length?'complete':''}"><button class="phase-button" data-action="phase" data-id="${i}" aria-expanded="${expanded===i}"><span class="phase-num">${done===p.items.length?icon('check'):String(i+1).padStart(2,'0')}</span><span class="phase-title">${p.title}<small>${p.subtitle}</small></span><span class="phase-count">${done}/${p.items.length}</span>${icon(i===expanded?'down':'chevron')}</button>${i===expanded?`<div class="tasks">${p.items.map(([k,label])=>`<div class="task ${c[k]?'done':''}"><i>${c[k]?icon('check'):''}</i><span>${label}</span></div>`).join('')}</div>`:''}</section>`}).join('');}
function renderScreen(){return sim.screen()||`<div class="screen-off"><div class="off-icon">${icon('power')}</div><div class="off-label">WORKSTATION 01 / STANDBY</div><h2>A blank machine. A fresh start.</h2><p>Your Windows Server journey begins here.<br>Connect your USB drive and Ethernet cable, then power on.</p><button class="green-btn" data-action="power">${icon('power')} Power on workstation</button><div class="off-footer"><span>${icon('server')} 4 vCPU</span><span>${icon('disk')} 8 GB RAM</span><span>${icon('disk')} 120 GB SSD</span><span>UEFI BIOS</span></div></div>`;}
function renderGuide(){if(resetOpen)return `<div class="outer-overlay" role="dialog" aria-modal="true" aria-label="Reset lab"><article class="guide"><h2>Start with a blank machine?</h2><p>This clears this browser’s simulated server, domain, users, folders, and mission progress.</p><button class="outline-btn" data-action="close-guide">Keep my lab</button> <button class="green-btn" data-action="confirm-reset">Reset lab</button></article></div>`;return `<div class="outer-overlay" role="dialog" aria-modal="true" aria-label="Field guide"><article class="guide"><button class="icon-btn close-guide" data-action="close-guide" aria-label="Close guide">${icon('close')}</button><div class="eyebrow">SERVERLAB / FIELD GUIDE</div><h2>From power-on to your first domain.</h2><p>This lab follows your Windows Server assignment. Use fictional passwords; password values are discarded after validation. Your progress is saved in this browser.</p><h3>01 — Connect & boot</h3><p>Connect the Ventoy USB drive and Ethernet cable below the monitor. Power on, then press <kbd>F2</kbd> or click Enter BIOS. On the Boot tab, select <b>UEFI: Ventoy USB</b> as Boot Option #1. Save & Exit with <kbd>F10</kbd>. Select the Windows Server ISO, then Boot in normal mode.</p><h3>02 — Install Windows Server</h3><p>Select your language, choose <b>Windows Server 2012 R2 Standard (Server with a GUI)</b>, accept the simulated license step, select Custom, and install on Drive 0. After the restart, set a fictional Administrator password: at least 8 characters and 3 of uppercase, lowercase, numbers, and symbols.</p><h3>03 — Create your domain</h3><p>In Server Manager, use <b>Manage → Add Roles and Features</b>. Select role-based installation, this server, and Active Directory Domain Services. Install the required features. Open <b>AD DS → More → Promote this server to a domain controller</b>. Choose <b>Add a new forest</b>, enter a domain such as <b>css.com</b>, keep both functional levels at <b>Windows Server 2012 R2</b>, and set a DSRM password. Continue through DNS, NetBIOS, Paths, Review, and Prerequisites. Install, then restart.</p><h3>04 — Organize & add users</h3><p>Open <b>Tools → Active Directory Users and Computers</b>. Right-click your domain → New → Organizational Unit. Enter a name and uncheck <b>Protect container from accidental deletion</b>. Right-click that OU → New → User. Enter a full name and logon name. Set a password, uncheck <b>User must change password at next logon</b>, and check <b>Password never expires</b>. Finish the wizard.</p><h3>05 — Create a shared folder</h3><p>Right-click the desktop → New → Folder (or use File Explorer). Enter a name. Right-click the folder → Properties → Sharing → Advanced Sharing. Check <b>Share this folder</b>, open Permissions, and allow <b>Full Control</b> for Everyone. Click OK in both dialogs. Finally, open the <b>Security</b> tab. The supplied assignment ends here; configuring a Folder Redirection policy is outside this mission.</p><h3>Explore your server</h3><p>Open apps from Start or the taskbar. Drag title bars, minimize windows, change IPv4 settings, and use the simulated PowerShell commands <b>help</b>, <b>ipconfig</b>, <b>hostname</b>, <b>whoami</b>, <b>dir</b>, <b>Get-ADUser</b>, and <b>Get-ADOrganizationalUnit</b>. Devices can be disconnected and reconnected at any time. BIOS and Ventoy support arrow keys and Enter.</p><footer>Educational simulation; no actual OS, services, or external programs execute. Lab password and permission choices follow your assignment. <a href="https://learn.microsoft.com/en-us/windows-server/identity/ad-ds/deploy/install-a-new-windows-server-2012-active-directory-forest--level-200-" target="_blank" rel="noreferrer">Microsoft AD DS reference</a> · <a href="https://ventoy.net/en/doc_start.html" target="_blank" rel="noreferrer">Ventoy reference</a></footer></article></div>`;}
function fitScreen(){const vp=$('#viewport');if(vp)$('#screen').style.setProperty('--scale',vp.clientWidth/1000);}
window.addEventListener('resize',fitScreen);
document.addEventListener('click',e=>{const b=e.target.closest('[data-action]');if(!b)return;const a=b.dataset.action;if(a==='usb'||a==='ethernet'){state[a]=!state[a];save();render();toast(`${a==='usb'?'Ventoy USB drive':'Ethernet cable'} ${state[a]?'connected':'disconnected'}.`);}if(a==='power')sim.power();if(a==='phase'){expanded=+b.dataset.id;render();}if(a==='guide'||a==='hint'){guideOpen=true;resetOpen=false;render();}if(a==='close-guide'||a==='lab'){guideOpen=false;resetOpen=false;render();}if(a==='fullscreen'){fullscreen=!fullscreen;render();}if(a==='reset'){guideOpen=true;resetOpen=true;render();}if(a==='confirm-reset'){sim.clear();state=initialState();expanded=0;guideOpen=resetOpen=false;save();render();toast('Your lab is ready for a fresh start.');}if(a.startsWith('os-'))sim.action(a.slice(3),b,e);});
document.addEventListener('keydown',e=>{if(e.key==='Escape'&&guideOpen){guideOpen=resetOpen=false;render();}});
if(document.modelContext?.registerTool){try{document.modelContext.registerTool({name:'read_lab_progress',title:'Read server lab progress',description:'Read the simulated machine status and the current mission checklist. Does not change the lab.',inputSchema:{type:'object',properties:{},additionalProperties:false},annotations:{readOnlyHint:true},execute:input=>{if(!input||typeof input!=='object'||Object.keys(input).length)throw new Error('Expected an empty object.');return {screen:state.screen,poweredOn:state.power,domain:state.domain||null,progress:progress(state),checks:checks(state)};}});}catch{}}
render();
